/* @autogenerated */
import {
  TenantTermsOfUseProjection,
  TenantTermsOfUseFilter,
} from 'app/features/access/tenant-terms-of-use/model/tenant-terms-of-use.model';
import { TenantTermsOfUseRepository } from 'app/features/access/tenant-terms-of-use/repository/tenant-terms-of-use-repository.service';
import { FormControl } from '@angular/forms';
import { Shift } from '@common/data/repository/repository.model';
import { input, effect, Component } from '@angular/core';

@Component({
  selector: 'tenant-terms-of-use-view-list',
  templateUrl: './tenant-terms-of-use-view-list.component.html',
  styleUrls: ['./tenant-terms-of-use-view-list.component.scss'],
  standalone: false,
})
export class TenantTermsOfUseViewListComponent {
  filters = input<TenantTermsOfUseFilter>();
  actionName = input<string>('tenant-terms-of-use');
  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  search = new FormControl<any>(undefined);
  list: Shift<TenantTermsOfUseProjection[], TenantTermsOfUseFilter>;

  constructor(repository: TenantTermsOfUseRepository) {
    this.list = repository.projections(['tenant']);
    effect(() => {
      setTimeout(() => this.makeSearch());
    });
  }
  makeSearch() {
    const result = { limit: 10 } as any;
    const filter = this.search.value;
    const external = this.filters();
    if (external?.search) {
      result.search = external.search;
    }
    if (external?.tenants) {
      result.tenants = external.tenants;
    }
    if (filter?.search) {
      result.search = filter.search;
    }
    if (filter?.tenants?.$ref) {
      result.tenants = filter.tenants.$ref;
    }
    this.list.fetch(result);
  }

  next() {
    this.list.next();
  }

  reload() {
    this.list.reset();
  }

  prev() {
    console.log('PREV');
  }
}
